def waitpid(child, flags): assert child == pid and flags == os.WNOHANG calls.append({"pid": child, "flags": flags, "monotonic": now[0]}) if outcome.startswith("late-"): now[0] = 100.2 if outcome in {"echild", "eio", "late-eio"}: number = errno.ECHILD if outcome == "echild" else errno.EIO raise OSError(number, "simulated worker reap errno") return original_waitpid(child, flags)
def forbidden_signal(*args): raise AssertionError("expired or terminal owner regained signal authority")
try: # Readiness is bounded independently of the synthetic runtime clock. import select
assert select.select([read_fd], [], [], 1)[0] assert os.read(read_fd, 1) == b"R" if outcome not in {"live", "late-live"}: # Register before releasing exit; observe without consuming status. queue = select.kqueue() try: event = select.kevent( pid, filter=select.KQ_FILTER_PROC, flags=select.KQ_EV_ADD, fflags=select.KQ_NOTE_EXIT, ) queue.control([event], 0, 0) os.write(release_write, b"X") events = queue.control(None, 1, 1) assert any(item.fflags & select.KQ_NOTE_EXIT for item in events) finally: queue.close() with monkeypatch.context() as patch: patch.setattr(time, "monotonic", lambda: now[0]) patch.setattr(os, "waitpid", waitpid) patch.setattr(os, "kill", forbidden_signal) patch.setattr(os, "killpg", forbidden_signal) worker_capture._reap(owner) assert len(calls) == 1 if outcome == "live" and at < 100: # A second pre-cutoff poll is still permitted. now[0] = 99.99 worker_capture._reap(owner) assert len(calls) == 2 attempts = len(calls) for expired in (100.0, 100.3, 100.5): now[0] = expired worker_capture._reap(owner) worker_capture._signal(owner, signal.SIGTERM) worker_capture._signal(owner, signal.SIGKILL) assert len(calls) == attempts > assert owner.reap_attempts == attempts E assert 0 == 1 E + where 0 = _Owner(pid=23798, shutdown_deadline_monotonic=100.0, ready=False, reaped=True, ownership_lost=False, returncode=7, signals=[], reap_errno=None, reap_attempts=0).reap_attempts
