def waitpid(child, flags): assert child == pid and flags == os.WNOHANG calls.append({"pid": child, "flags": flags, "monotonic": now[0]}) if outcome.startswith("late-"): now[0] = 100.2 if outcome in {"echild", "eio", "late-eio"}: number = errno.ECHILD if outcome == "echild" else errno.EIO raise OSError(number, "simulated worker reap errno") return original_waitpid(child, flags)
